local AstrolabeMaker = {}
local PRODUCTS = {
    brass_astrolabe = { name = "Medeninast astrolab", brassCost = 2, time = 4, cost = 80, accuracy = 50, prestige = 3, description = "Medeninast astrolab za merjenje zvezd." },
    silver_astrolabe = { name = "Srebrn astrolab", silverCost = 2, brassCost = 1, time = 6, cost = 200, accuracy = 70, prestige = 7, happiness = 1, description = "Srebrn astrolab za fine meritve." },
    engraved_astrolabe = { name = "Vgraviran astrolab", silverCost = 2, brassCost = 1, time = 8, cost = 450, accuracy = 82, prestige = 12, happiness = 2, description = "Vgraviran astrolab z zvezdno karto." },
    silver_retrograde_astrolabe = { name = "Srebrno retrogradni astrolab", silverCost = 2, goldCost = 1, brassCost = 1, time = 11, cost = 900, accuracy = 90, prestige = 18, happiness = 3, description = "Astrolab z retrogradnimi gibanji za plemiče." },
    gold_plated_astrolabe = { name = "Pozlačen astrolab", goldCost = 2, silverCost = 1, brassCost = 1, jewelCost = 1, time = 14, cost = 1800, accuracy = 96, prestige = 30, happiness = 6, description = "Pozlačen astrolab z draguljem za visoke plemiče." },
    royal_grand_astrolabe = { name = "Kraljevski veliki astrolab", goldCost = 3, silverCost = 2, jewelCost = 2, pearlCost = 1, brassCost = 1, time = 20, cost = 3500, accuracy = 100, prestige = 60, happiness = 12, description = "Veliki kraljevski astrolab z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Astrolabska delavnica", cost = { gold = 320, wood = 130, stone = 250 }, upkeep = 8, qualityBonus = 5 },
    instrument_forge = { name = "Inštrumentska kovačija", cost = { gold = 1100, wood = 280, stone = 500, brass = 8 }, upkeep = 28, qualityBonus = 18 },
    engraving_room = { name = "Vgravirnica", cost = { gold = 2600, wood = 400, stone = 800, silver = 40, steel = 8 }, upkeep = 65, qualityBonus = 30 },
    royal_instrument_atelier = { name = "Kraljevski atelje inštrumentov", cost = { gold = 11000, wood = 600, stone = 1200, gold = 80, jewel = 25 }, upkeep = 220, qualityBonus = 55, prestigeBonus = 50 },
}
AstrolabeMaker.brassStock = 14; AstrolabeMaker.silverStock = 8; AstrolabeMaker.goldStock = 6; AstrolabeMaker.jewelStock = 6; AstrolabeMaker.pearlStock = 4
AstrolabeMaker.productStock = {}; AstrolabeMaker.buildings = {}; AstrolabeMaker.maker = nil; AstrolabeMaker.activeMaking = {}; AstrolabeMaker.totalProducts = 0; AstrolabeMaker.dayTimer = 0
function AstrolabeMaker.init() AstrolabeMaker.brassStock=14; AstrolabeMaker.silverStock=8; AstrolabeMaker.goldStock=6; AstrolabeMaker.jewelStock=6; AstrolabeMaker.pearlStock=4; AstrolabeMaker.productStock={}; AstrolabeMaker.buildings={}; AstrolabeMaker.maker=nil; AstrolabeMaker.activeMaking={}; AstrolabeMaker.totalProducts=0; AstrolabeMaker.dayTimer=0; print("[AstrolabeMaker] Royal Astrolabe Maker System initialized (6 products, 4 buildings)") end
function AstrolabeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; AstrolabeMaker.maker={name=n or ("Astrolabar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Astrolabar najet: %s (spretnost: %d)",AstrolabeMaker.maker.name,s),"success") end; return true end
function AstrolabeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function AstrolabeMaker.build(id) local ok,e=AstrolabeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(AstrolabeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function AstrolabeMaker.getQualityBonus() local b=0; for _,bd in ipairs(AstrolabeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function AstrolabeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.brassCost and AstrolabeMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and AstrolabeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and AstrolabeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and AstrolabeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and AstrolabeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #AstrolabeMaker.buildings==0 then return false,"Potrebna delavnica" end; if not AstrolabeMaker.maker then return false,"Potreben astrolabar" end; return true end
function AstrolabeMaker.make(pt,qty) qty=qty or 1; local ok,e=AstrolabeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.brassCost then AstrolabeMaker.brassStock=AstrolabeMaker.brassStock-d.brassCost*qty end; if d.silverCost then AstrolabeMaker.silverStock=AstrolabeMaker.silverStock-d.silverCost*qty end; if d.goldCost then AstrolabeMaker.goldStock=AstrolabeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then AstrolabeMaker.jewelStock=AstrolabeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then AstrolabeMaker.pearlStock=AstrolabeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if AstrolabeMaker.maker then t=math.max(1,t-math.floor(AstrolabeMaker.maker.skill/12)) end; table.insert(AstrolabeMaker.activeMaking,{id="astrolabe_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,accuracy=d.accuracy or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function AstrolabeMaker.completeMaking(m) local q=1.0+(AstrolabeMaker.getQualityBonus()/100); if AstrolabeMaker.maker then q=q+(AstrolabeMaker.maker.skill/150) end; q=math.min(2.5,q); AstrolabeMaker.productStock[m.productType]=(AstrolabeMaker.productStock[m.productType] or 0)+m.quantity; AstrolabeMaker.totalProducts=AstrolabeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if AstrolabeMaker.maker then AstrolabeMaker.maker.itemsMade=AstrolabeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then AstrolabeMaker.maker.skill=math.min(100,AstrolabeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Astrolab izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"astrolabe.completed",{productName=m.productName,accuracy=m.accuracy,prestige=m.prestige,happiness=m.happiness}) end end
function AstrolabeMaker.update(dt) if not _G.state then return end; AstrolabeMaker.dayTimer=AstrolabeMaker.dayTimer+dt; if AstrolabeMaker.dayTimer>=30 then AstrolabeMaker.dayTimer=0; for i=#AstrolabeMaker.activeMaking,1,-1 do local m=AstrolabeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then AstrolabeMaker.completeMaking(m); table.remove(AstrolabeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(AstrolabeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if AstrolabeMaker.maker then tu=tu+18 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function AstrolabeMaker.getStats() return {brassStock=AstrolabeMaker.brassStock,silverStock=AstrolabeMaker.silverStock,goldStock=AstrolabeMaker.goldStock,jewelStock=AstrolabeMaker.jewelStock,pearlStock=AstrolabeMaker.pearlStock,productStock=AstrolabeMaker.productStock,numBuildings=#AstrolabeMaker.buildings,hasMaker=AstrolabeMaker.maker~=nil,makerName=AstrolabeMaker.maker and AstrolabeMaker.maker.name or "—",makerSkill=AstrolabeMaker.maker and AstrolabeMaker.maker.skill or 0,activeMaking=#AstrolabeMaker.activeMaking,totalProducts=AstrolabeMaker.totalProducts} end
return AstrolabeMaker
